(function(){
  'use strict';
  var D = window.DGZ_TARIFS;

  /* ---- le CSS specifique aux blocs voyage avec eux : lien « Voir un
     exemple » + icones vivantes des cartes site web. Doublon inoffensif
     sur creation-site-web.html (regles identiques). ---- */
  if (!document.getElementById('dgzTarifsCss')){
    var feuille = document.createElement('style');
    feuille.id = 'dgzTarifsCss';
    feuille.textContent = "/* styles portes par les blocs (source : creation-site-web.html) */\n.icm-k1{animation:icmK 3.2s ease-in-out infinite}\n\n  .icm-k2{animation:icmK 3.2s ease-in-out infinite reverse; animation-delay:-.8s}\n\n  .icm-k3{animation:icmK 3.2s ease-in-out infinite; animation-delay:-1.6s}\n\n  @keyframes icmK{0%,100%{transform:translateX(0)} 50%{transform:translateX(2.4px)}}\n\n  @media (prefers-reduced-motion:reduce){ .icm-k1,.icm-k2,.icm-k3{animation:none}}\n\n@media (prefers-reduced-motion: no-preference){\n    @keyframes prDerive{0%,100%{transform:translateY(1.1px)} 50%{transform:translateY(-1.3px)}}\n\n    @keyframes prSouffle{0%,100%{opacity:.32; transform:scaleY(.74)} 50%{opacity:.95; transform:scaleY(1.10)}}\n\n    @keyframes prCligne{0%,100%{opacity:.30} 16%{opacity:1} 44%{opacity:.30}}\n\n    @keyframes prCharge{0%,100%{transform:scaleX(.58)} 55%{transform:scaleX(1)}}\n\n    \n\n    .ic-fusee .ic-corps{animation:prDerive 6.4s ease-in-out infinite}\n\n    .ic-fusee .ic-feu{transform-origin:50% 0%; animation:prSouffle 5.2s ease-in-out infinite}\n\n    .ic-fenetre .ic-pt{animation:prCligne 5.4s ease-in-out infinite}\n\n    .ic-fenetre .ic-pt2{animation-delay:.30s}\n\n    .ic-fenetre .ic-pt3{animation-delay:.60s}\n\n    .ic-fenetre .ic-ln{transform-origin:0% 50%; animation:prCharge 6s ease-in-out infinite}\n\n    .ic-fenetre .ic-ln2{animation-delay:.55s}\n\n    @keyframes prDecolle{\n      0%{transform:translate3d(0,0,0) rotate(0deg)}\n      34%{transform:translate3d(.6px,-3px,0) rotate(-6deg)}\n      58%{transform:translate3d(0,-1.2px,0) rotate(1.6deg)}\n      100%{transform:translate3d(0,0,0) rotate(0deg)}}\n\n    @keyframes prMonte{0%,100%{transform:translate3d(0,0,0)} 45%{transform:translate3d(0,-1.6px,0)}}\n\n    \n\n    .pr-carte.pr-geste .ic-fusee, .pr-carte:hover .ic-fusee,\n    .pr-carte:focus-within .ic-fusee{animation:prDecolle .72s cubic-bezier(.22,1,.36,1) 1 both}\n\n    .pr-carte.pr-geste .ic-fenetre, .pr-carte:hover .ic-fenetre,\n    .pr-carte:focus-within .ic-fenetre{animation:prMonte .62s cubic-bezier(.22,1,.36,1) 1 both}}\n\n.pr-exemple{margin-top:13px; align-self:center; cursor:pointer;\n    position:relative; overflow:hidden;\n    display:inline-flex; align-items:center; justify-content:center; gap:9px;\n    min-height:40px; padding:0 20px; border-radius:999px;\n    background:rgba(255,255,255,.44); color:var(--ink-soft);\n    box-shadow:inset 0 0 0 1px rgba(16,17,20,.20),\n      inset 0 1px 0 rgba(255,255,255,.85), 0 1px 0 rgba(255,255,255,.60);\n    font-family:var(--f-disp); font-size:11.5px; font-weight:600;\n    letter-spacing:.05em; text-transform:uppercase; line-height:1;\n    text-decoration:none;\n    transition:background-color .25s ease, color .25s ease,\n      box-shadow .25s ease, transform .25s ease}\n\n  .pr-exemple > *{position:relative; z-index:1}\n\n  .pr-exemple svg{width:14px; height:14px; flex:none;\n    fill:none; stroke:currentColor; stroke-width:1.9;\n    stroke-linecap:round; stroke-linejoin:round; transition:transform .22s ease}\n\n  .pr-exemple::after{content:\"\"; position:absolute; inset:0; z-index:0;\n    pointer-events:none; border-radius:inherit;\n    background:linear-gradient(100deg, rgba(255,255,255,0) 40%,\n      rgba(255,255,255,.85) 50%, rgba(255,255,255,0) 60%);\n    transform:translate3d(-100%,0,0); transition:none}\n\n  @media (hover:hover) and (pointer:fine){\n    .pr-exemple:hover{background:rgba(255,255,255,.78); color:var(--ink);\n      box-shadow:inset 0 0 0 1px rgba(16,17,20,.42),\n        inset 0 1px 0 rgba(255,255,255,.95), 0 1px 0 rgba(255,255,255,.70);\n      transform:translateY(-1px)}\n\n    .pr-exemple:hover svg{transform:scale(1.12)}\n\n    .pr-exemple:hover::after{transform:translate3d(100%,0,0);\n      transition:transform .6s ease}}\n\n  .pr-carte .pr-exemple{margin-top:auto}\n\n  .pr-carte .pr-exemple + .pr-cta{margin-top:10px}\n\n  .pr-exemple:focus-visible{outline:2px solid var(--ink); outline-offset:3px}\n\n  @media (prefers-reduced-motion: reduce){\n    .pr-exemple, .pr-exemple svg, .pr-exemple::after{transition:none}\n\n    .pr-exemple:hover svg{transform:none}\n\n    .pr-exemple::after{display:none}}";
    document.head.appendChild(feuille);
  }

  /* ---- pages services : le reservoir devient le bloc verbatim ---- */
  var basins = document.querySelectorAll('[data-tarifs]');
  Array.prototype.forEach.call(basins, function(ph){
    var d = D[ph.getAttribute('data-tarifs')];
    if (!d) return;
    var t = document.createElement('template');
    t.innerHTML = d.bloc;
    ph.replaceWith(t.content);
  });

  /* ---- prix de depart : plus petit « Des N » d'un bloc ---- */
  function depart(bloc){
    var t = document.createElement('template');
    t.innerHTML = bloc;
    var meilleur = null;
    var prix = t.content.querySelectorAll('.pr-prix');
    Array.prototype.forEach.call(prix, function(p){
      var av = p.querySelector('.pr-prix-av');
      var st = p.querySelector('.pr-prix-ligne strong');
      if (!av || !st) return;
      if (av.textContent.trim().toLowerCase().indexOf('d\u00e8s') !== 0) return;
      var n = parseInt(st.textContent.replace(/\D/g, ''), 10);
      if (!n) return;
      if (!meilleur || n < meilleur.n){
        meilleur = {n:n, txt:st.textContent.trim(),
                    mois:!!p.querySelector('.pr-prix-mois')};
      }
    });
    return meilleur
      ? 'd\u00e8s ' + meilleur.txt + '\u00a0CHF' + (meilleur.mois ? '/mois' : '')
      : '';
  }
  var caches = {};
  window.DGZ_TARIFS_depart = function(cle){
    if (!(cle in caches)) caches[cle] = D[cle] ? depart(D[cle].bloc) : '';
    return caches[cle];
  };
  Array.prototype.forEach.call(document.querySelectorAll('[data-tarif-depart]'), function(el){
    var t = window.DGZ_TARIFS_depart(el.getAttribute('data-tarif-depart'));
    if (t) el.textContent = t;
  });
})();
